// Tạo chuỗi payload EMV VietQR (chuẩn NAPAS) để vẽ mã QR chuyển khoản.
// Cần kèm hàm crc16ccitt (xem mẫu "CRC16-CCITT cho VietQR").

function tlv(id, value) {
  const len = new TextEncoder().encode(value).length; // độ dài tính bằng BYTE
  return id + String(len).padStart(2, '0') + value;
}

function vietqrPayload({ bin, account, amount = 0, memo = '' }) {
  const cleanMemo = memo
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd').replace(/Đ/g, 'D')
    .toUpperCase().trim(); // nội dung phải bỏ dấu + viết hoa
  const amt = Number(amount) > 0 ? String(amount).replace(/[^0-9]/g, '') : '';
  const merchant = tlv('00', 'A000000727')
    + tlv('01', tlv('00', bin) + tlv('01', account))
    + tlv('02', 'QRIBFTTA');
  let payload = tlv('00', '01') + tlv('01', amt ? '12' : '11')
    + tlv('38', merchant) + tlv('53', '704');
  if (amt) payload += tlv('54', amt);
  payload += tlv('58', 'VN');
  if (cleanMemo) payload += tlv('62', tlv('08', cleanMemo));
  payload += '6304';
  return payload + crc16ccitt(payload).toString(16).toUpperCase().padStart(4, '0');
}

// Ví dụ (test vector chuẩn):
vietqrPayload({ bin: '970414', account: '883866666', amount: 50000 });
// → '00020101021238530010A0000007270123000697041401098838666660208QRIBFTTA53037045405500005802VN630494B2'
vietqrPayload({ bin: '970414', account: '883866666' }); // QR tĩnh, không gắn số tiền
// → '00020101021138530010A0000007270123000697041401098838666660208QRIBFTTA53037045802VN6304A99A'

// CRC16-CCITT-FALSE: đa thức 0x1021, giá trị khởi đầu 0xFFFF.
// Dùng cho trường 63 (mã kiểm tra) của mã QR VietQR.
// Kiểm tra: crc16ccitt('123456789') === 0x29b1.
function crc16ccitt(str) {
  let crc = 0xffff;
  for (let i = 0; i < str.length; i++) {
    crc ^= str.charCodeAt(i) << 8;
    for (let j = 0; j < 8; j++) {
      crc = (crc & 0x8000) ? ((crc << 1) ^ 0x1021) : (crc << 1);
      crc &= 0xffff;
    }
  }
  return crc;
}

// Ví dụ:
crc16ccitt('123456789'); // 0x29b1

// Tạo chuỗi nội dung mã QR WiFi — điện thoại quét là tự kết nối mạng.
// Dùng với bất kỳ thư viện vẽ QR nào, hoặc công cụ "Tạo mã QR" trên web này.
function wifiQrString({ ssid, password = '', encryption = 'WPA', hidden = false }) {
  const esc = (s) => String(s).replace(/([\\;,:"])/g, '\\$1'); // thoát ký tự đặc biệt
  const enc = password ? encryption.toUpperCase() : 'nopass';
  return `WIFI:T:${enc};S:${esc(ssid)};P:${esc(password)};H:${hidden ? 'true' : 'false'};;`;
}

// Ví dụ:
wifiQrString({ ssid: 'Nha Toi 5G', password: 'matkhau123' });
// → 'WIFI:T:WPA;S:Nha Toi 5G;P:matkhau123;H:false;;'
wifiQrString({ ssid: 'Quan Ca Phe', password: '' });
// → 'WIFI:T:nopass;S:Quan Ca Phe;P:;H:false;;'

// Kiểm tra + chuẩn hóa số điện thoại Việt Nam
// (10 số, đầu 03/05/07/08/09 — đầu 01 đã chuyển đổi từ 2018).
function normalizePhone(input) {
  const digits = String(input).replace(/[^0-9+]/g, '');
  if (digits.startsWith('+84')) return '0' + digits.slice(3);
  if (digits.startsWith('84') && digits.length === 11) return '0' + digits.slice(2);
  return digits;
}

function isVietnamesePhone(input) {
  return /^0(3|5|7|8|9)\d{8}$/.test(normalizePhone(input));
}

// Ví dụ:
isVietnamesePhone('090 123 45 67');  // true
isVietnamesePhone('+84901234567');   // true
isVietnamesePhone('0123456789');     // false (đầu 01 không còn dùng)
isVietnamesePhone('090123456');      // false (thiếu số)
normalizePhone('+84 90 123 45 67'); // '0901234567'

// Kiểm tra CCCD (12 số) và mã số thuế (10 số + số kiểm tra, hoặc 13 số).
// CCCD: 3 số đầu = mã tỉnh (001–096), số thứ 4 = giới tính + thế kỷ,
// 2 số tiếp = năm sinh, 6 số cuối = số ngẫu nhiên.
function isCCCD(input) {
  const s = String(input).trim();
  if (!/^\d{12}$/.test(s)) return false;
  const province = Number(s.slice(0, 3));
  return province >= 1 && province <= 96;
}

// Mã số thuế 10 số: số thứ 10 là số kiểm tra, tính từ 9 số đầu với
// trọng số 31, 29, 23, 19, 17, 13, 7, 5, 3.
function isMaSoThue(input) {
  const s = String(input).trim();
  const m = s.match(/^(\d{10})(?:-(\d{3}))?$/);
  if (!m) return false;
  const d = m[1].split('').map(Number);
  const weights = [31, 29, 23, 19, 17, 13, 7, 5, 3];
  const sum = weights.reduce((acc, w, i) => acc + w * d[i], 0);
  let check = 10 - (sum % 11);
  if (check === 10) check = 0;
  return check === d[9];
}

// Ví dụ:
isCCCD('079095012345');       // true (079 = TP.HCM)
isCCCD('07909501234');        // false (thiếu số)
isMaSoThue('0100109106');     // true
isMaSoThue('0100109106-001'); // true (mã chi nhánh)
isMaSoThue('0100109107');     // false (sai số kiểm tra)

// Đọc số nguyên thành chữ tiếng Việt (0 → "không đồng").
// Dùng cho hóa đơn, phiếu thu, hợp đồng. Hỗ trợ tới dưới 1 triệu tỷ.
const ONES = ['không', 'một', 'hai', 'ba', 'bốn', 'năm', 'sáu', 'bảy', 'tám', 'chín'];
const GROUPS = ['', 'nghìn', 'triệu', 'tỷ', 'nghìn tỷ', 'triệu tỷ'];

function readThree(n, full) {
  const hundred = Math.floor(n / 100);
  const ten = Math.floor((n % 100) / 10);
  const one = n % 10;
  const words = [];
  if (hundred > 0) words.push(ONES[hundred], 'trăm');
  else if (full) words.push('không', 'trăm');
  if (ten > 1) {
    words.push(ONES[ten], 'mươi');
    if (one === 1) words.push('mốt');
    else if (one === 5) words.push('lăm');
    else if (one > 0) words.push(ONES[one]);
  } else if (ten === 1) {
    words.push('mười');
    if (one === 5) words.push('lăm');
    else if (one > 0) words.push(ONES[one]);
  } else if (one > 0) {
    if (hundred > 0 || full) words.push('lẻ');
    words.push(ONES[one]);
  }
  return words.join(' ');
}

function docSoThanhChu(num) {
  const n = Math.trunc(Math.abs(Number(num)));
  if (!Number.isFinite(n) || n >= 1e15) return '';
  if (n === 0) return 'không đồng';
  const groups = [];
  let rest = n;
  while (rest > 0) { groups.push(rest % 1000); rest = Math.floor(rest / 1000); }
  const parts = [];
  for (let i = groups.length - 1; i >= 0; i--) {
    if (groups[i] === 0) continue;
    const full = i < groups.length - 1; // nhóm sau nhóm đầu thì đọc đủ "không trăm"
    parts.push(readThree(groups[i], full) + (GROUPS[i] ? ' ' + GROUPS[i] : ''));
  }
  const text = parts.join(' ').replace(/\s+/g, ' ').trim();
  return text.charAt(0).toUpperCase() + text.slice(1) + ' đồng';
}

// Ví dụ:
docSoThanhChu(50000);   // 'Năm mươi nghìn đồng'
docSoThanhChu(1234567); // 'Một triệu hai trăm ba mươi bốn nghìn năm trăm sáu mươi bảy đồng'
docSoThanhChu(1005);    // 'Một nghìn không trăm lẻ năm đồng'
docSoThanhChu(21);      // 'Hai mươi mốt đồng'

// Bỏ dấu tiếng Việt: "Tiện Ích Hub" → "Tien Ich Hub".
// Dùng cho tìm kiếm không dấu, chuẩn hóa nội dung VietQR, tạo slug.
function boDau(str) {
  return String(str)
    .normalize('NFD')                // tách dấu khỏi chữ cái
    .replace(/[\u0300-\u036f]/g, '')  // xóa các dấu đã tách
    .replace(/đ/g, 'd')              // đ/Đ không tách được bằng NFD
    .replace(/Đ/g, 'D');
}

// Ví dụ:
boDau('Tiện Ích Hub — Công cụ miễn phí'); // 'Tien Ich Hub — Cong cu mien phi'
boDau('Đặng Văn Lâm');                     // 'Dang Van Lam'

// Tạo slug URL từ tiêu đề tiếng Việt (dùng cho đường dẫn bài viết).
function taoSlug(str) {
  return String(str)
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd').replace(/Đ/g, 'D')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-') // ký tự khác chữ/số → dấu gạch ngang
    .replace(/^-+|-+$/g, '');    // cắt gạch ngang thừa ở 2 đầu
}

// Ví dụ:
taoSlug('Tiện Ích Hub — Công cụ miễn phí!'); // 'tien-ich-hub-cong-cu-mien-phi'
taoSlug('  Ăn gì ở Đà Lạt?  ');              // 'an-gi-o-da-lat'

// Định dạng tiền Việt bằng Intl.NumberFormat — có sẵn trong trình duyệt,
// không cần thư viện.
function dinhDangVND(soTien) {
  return new Intl.NumberFormat('vi-VN', {
    style: 'currency',
    currency: 'VND',
    maximumFractionDigits: 0,
  }).format(soTien);
}

function dinhDangSo(so, soThapPhan = 0) {
  return new Intl.NumberFormat('vi-VN', {
    minimumFractionDigits: soThapPhan,
    maximumFractionDigits: soThapPhan,
  }).format(so);
}

// Ví dụ:
dinhDangVND(1234567);    // '1.234.567 ₫'
dinhDangSo(1234.567, 2); // '1.234,57'

// Lãi kép + tiền trả góp hằng tháng (công thức PMT của ngân hàng).
// laiSuatNam: dạng thập phân (12%/năm → 0.12).
function laiKep(goc, laiSuatNam, soNam) {
  return goc * Math.pow(1 + laiSuatNam, soNam);
}

function traGopHangThang(goc, laiSuatNam, soThang) {
  const r = laiSuatNam / 12;
  if (r === 0) return goc / soThang;
  return (goc * r) / (1 - Math.pow(1 + r, -soThang));
}

// Ví dụ:
laiKep(100_000_000, 0.07, 5);             // ≈ 140.255.173 (gửi 100tr, 7%/năm, 5 năm)
traGopHangThang(500_000_000, 0.12, 240);  // ≈ 5.505.431/tháng (vay 500tr, 12%/năm, 20 năm)

// Lấy tỷ giá USD → VND từ open.er-api.com (API miễn phí, không cần key).
// Trang này dùng chính nguồn này cho thẻ Tỷ giá trên trang chủ.
async function layTyGiaVND() {
  const res = await fetch('https://open.er-api.com/v6/latest/USD');
  if (!res.ok) throw new Error('Không lấy được tỷ giá (HTTP ' + res.status + ')');
  const data = await res.json();
  return data.rates.VND; // VD: 26200 → 1 USD = 26.200 ₫
}

// Ví dụ:
// layTyGiaVND().then((rate) => console.log('1 USD =', rate, 'VND'));

// Giải mã phần payload của JWT ở phía client.
// KHÔNG kiểm tra chữ ký — chỉ dùng để đọc thông tin hiển thị,
// không dùng để xác thực (việc đó phải làm ở server).
function giaiMaJwt(token) {
  const payload = String(token).split('.')[1] || '';
  const base64 = payload.replace(/-/g, '+').replace(/_/g, '/');
  const json = decodeURIComponent(
    atob(base64).split('').map((c) =>
      '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2)).join(''));
  return JSON.parse(json);
}

// Ví dụ:
giaiMaJwt('eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiIxMjMiLCJuYW1lIjoiTmd1eeG7hW4gQW4ifQ.abc');
// → { sub: '123', name: 'Nguyễn An' }

// Debounce: chỉ chạy sau khi người dùng ngừng thao tác một lúc
// (ô tìm kiếm). Throttle: chạy tối đa 1 lần mỗi khoảng thời gian
// (sự kiện cuộn trang, thay đổi kích thước cửa sổ).
function debounce(fn, delay = 300) {
  let timer;
  return function (...args) {
    clearTimeout(timer);
    timer = setTimeout(() => fn.apply(this, args), delay);
  };
}

function throttle(fn, limit = 200) {
  let lastRun = 0;
  let timer;
  return function (...args) {
    const now = Date.now();
    const remaining = limit - (now - lastRun);
    clearTimeout(timer);
    if (remaining <= 0) {
      lastRun = now;
      fn.apply(this, args);
    } else {
      timer = setTimeout(() => {
        lastRun = Date.now();
        fn.apply(this, args);
      }, remaining);
    }
  };
}

// Ví dụ:
const timKiem = debounce((tuKhoa) => console.log('Tìm:', tuKhoa), 300);
timKiem('ti'); timKiem('tien'); timKiem('tien ich'); // chỉ chạy 1 lần với 'tien ich'

// fetch() có thời gian chờ tối đa — quá hạn thì hủy request.
// (Mặc định fetch chờ tới khi mạng tự ngắt, có thể rất lâu.)
async function fetchWithTimeout(url, options = {}, timeoutMs = 5000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    return await fetch(url, { ...options, signal: controller.signal });
  } finally {
    clearTimeout(timer);
  }
}

